import { revalidatePath } from "next/cache";
import { cookies } from "next/headers";

const NOTIFICATION_COOKIE = "notifications";

function getNotificationPreference() {
  const value = cookies().get(NOTIFICATION_COOKIE)?.value;
  return value === "off" ? "off" : "on";
}

export default function Home() {
  const preference = getNotificationPreference();

  async function toggleNotifications() {
    "use server";

    const current = getNotificationPreference();
    const next = current === "on" ? "off" : "on";

    cookies().set(NOTIFICATION_COOKIE, next, {
      httpOnly: true,
      sameSite: "lax",
      path: "/",
    });

    revalidatePath("/");
  }

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently <strong>{preference}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {preference === "on" ? "off" : "on"}
        </button>
      </form>
    </main>
  );
}

