import { revalidatePath } from "next/cache";
import { cookies } from "next/headers";

const NOTIFICATION_COOKIE = "notifications";

async function getNotificationPreference() {
  const cookieStore = await cookies();
  const value = cookieStore.get(NOTIFICATION_COOKIE)?.value;
  return value === "off" ? "off" : "on";
}

export default async function Home() {
  const preference = await getNotificationPreference();

  async function toggleNotifications() {
    "use server";

    const current = await getNotificationPreference();
    const next = current === "on" ? "off" : "on";

    const cookieStore = await cookies();
    cookieStore.set(NOTIFICATION_COOKIE, next, {
      httpOnly: true,
      sameSite: "lax",
      path: "/",
    });

    revalidatePath("/");
  }

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently <strong>{preference}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {preference === "on" ? "off" : "on"}
        </button>
      </form>
    </main>
  );
}
